package com.jnapanam.sportszone.release1.service;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class Release1OperationsService{private final JdbcTemplate j;public Release1OperationsService(JdbcTemplate j){this.j=j;}
 @Transactional public Map<String,Object> support(UUID actor,UUID ticket,String action,String details,UUID assignee){String a=action.toUpperCase();if(a.equals("ASSIGN"))j.update("update support_tickets set assigned_to=?,updated_at=now() where id=?",assignee,ticket);if(a.equals("ESCALATE"))j.update("update support_tickets set priority='URGENT',updated_at=now() where id=?",ticket);if(a.equals("RESOLVE"))j.update("update support_tickets set status='RESOLVED',resolution=?,resolved_at=now(),updated_at=now() where id=?",details,ticket);UUID id=UUID.randomUUID();j.update("insert into support_ticket_history(id,ticket_id,action,details,actor_user_id) values(?,?,?,?,?)",id,ticket,a,details,actor);return one("select * from support_tickets where id=?",ticket);}
 @Transactional public Map<String,Object> inventory(UUID facility,String name,int total,long deposit){List<Map<String,Object>> x=j.queryForList("select id from equipment_inventory where facility_id is not distinct from ? and lower(equipment_name)=lower(?)",facility,name);if(x.isEmpty()){UUID id=UUID.randomUUID();j.update("insert into equipment_inventory(id,facility_id,equipment_name,total_quantity,available_quantity,deposit_paise) values(?,?,?,?,?,?)",id,facility,name,total,total,deposit);return one("select * from equipment_inventory where id=?",id);}UUID id=(UUID)x.get(0).get("id");j.update("update equipment_inventory set total_quantity=?,available_quantity=least(available_quantity,?),deposit_paise=? where id=?",total,total,deposit,id);return one("select * from equipment_inventory where id=?",id);}
 public List<Map<String,Object>> inventory(){return j.queryForList("select ei.*,f.name facility_name from equipment_inventory ei left join facilities f on f.id=ei.facility_id where active=true order by equipment_name");}
 @Transactional public Map<String,Object> family(UUID membership,UUID dependent){UUID id=UUID.randomUUID();j.update("insert into membership_family_members(id,membership_id,dependent_id) values(?,?,?) on conflict(membership_id,dependent_id) do nothing",id,membership,dependent);return one("select * from membership_family_members where membership_id=? and dependent_id=?",membership,dependent);}
 @Transactional public Map<String,Object> installment(UUID enrollment,int no,long amount,String due){UUID id=UUID.randomUUID();j.update("insert into training_installments(id,enrollment_id,installment_no,amount_paise,due_date) values(?,?,?,?,?::date)",id,enrollment,no,amount,due);return one("select * from training_installments where id=?",id);}
 @Transactional public Map<String,Object> standing(UUID tournament,UUID team,int played,int won,int drawn,int lost,int points,int sf,int sa,double tie){UUID id=UUID.randomUUID();j.update("insert into tournament_standings(id,tournament_id,team_id,played,won,drawn,lost,points,score_for,score_against,tie_break_value) values(?,?,?,?,?,?,?,?,?,?,?) on conflict(tournament_id,team_id) do update set played=excluded.played,won=excluded.won,drawn=excluded.drawn,lost=excluded.lost,points=excluded.points,score_for=excluded.score_for,score_against=excluded.score_against,tie_break_value=excluded.tie_break_value",id,tournament,team,played,won,drawn,lost,points,sf,sa,tie);return one("select * from tournament_standings where tournament_id=? and team_id=?",tournament,team);}
 public List<Map<String,Object>> standings(UUID tournament){return j.queryForList("select * from tournament_standings where tournament_id=? order by points desc,tie_break_value desc,(score_for-score_against) desc",tournament);}
 private Map<String,Object> one(String q,Object...a){return j.queryForMap(q,a);}}
